def solve(gi):
    gi=np.array(gi); h,w=gi.shape
    SR=[r for r in range(h) if len(set(gi[r].tolist()))==1]
    SC=[c for c in range(w) if len(set(gi[:,c].tolist()))==1]
    # band index for each row/col
    ri={}
    prev=-1; idx=0
    for b in [-1]+SR+[h]:
        for r in range(prev+1,b): ri[r]=idx
        prev=b; idx+=1
    pj={}
    prev=-1; idx=0
    for b in [-1]+SC+[w]:
        for c in range(prev+1,b): pj[c]=idx
        prev=b; idx+=1
    nrow,ncl=idx,idx
    occ=[[False]*ncl for _ in range(nrow)]
    marks=[]
    for r in range(h):
        for c in range(w):
            if gi[r,c]!=1 and r not in SR and c not in SC:
                v=int(gi[r,c]); bi,pj_=ri[r],pj[c]
                occ[bi][pj_]=True
                marks.append((bi,pj_,v,r,c))
    out=gi.copy()
    def rr(bi): return [x for x in range(h) if ri[x]==bi][0]
    def cc_(bj): return [x for x in range(w) if pj[x]==bj][0]
    for bi,bj,v,r,c in marks:
        row = rr(bi); col = cc_(bj)
        for sgn in (-1,1):
            k=bj+sgn
            while 0<=k<ncl and not occ[bi][k]:
                occ[bi][k]=True
                out[row,col+(cc_(k)-col)*sgn]=v
                k+=sgn
        for sgn in (-1,1):
            k=bi+sgn
            while 0<=k<nrow and not occ[k][bj]:
                occ[k][bj]=True
                out[row+(rr(k)-row)*sgn,col]=v
                k+=sgn
    return out

